import json
import shutil
import subprocess
from pathlib import Path

def _read_keystore_metadata(src: Path) -> dict:
    # Read the keystore JSON (before moving) to capture address and version info
    try:
        data = json.loads(src.read_text())
        return {'address': data.get('address'), 'version': data.get('version')}
    except (OSError, ValueError):
        return {}

def archive_keystore_and_backup(keystore_path: str, archive_dir: str, backup_script: str) -> dict:
    src = Path(keystore_path)
    dest_dir = Path(archive_dir)
    dest_dir.mkdir(parents=True, exist_ok=True)
    meta = _read_keystore_metadata(src)
    dest = shutil.move(str(src), str(dest_dir / src.name))
    proc = subprocess.run(['bash', backup_script, str(dest_dir)], capture_output=True, text=True, timeout=300)
    return {'moved_to': dest, 'exit_code': proc.returncode, 'stdout': proc.stdout[-500:], 'stderr': proc.stderr[-500:], 'keystore_meta': meta}
